package `in`.paisetree.kyc.verify

import `in`.paisetree.kyc.model.Applicant
import `in`.paisetree.kyc.model.Reviewer
import `in`.paisetree.kyc.verify.uidai.UidaiStubClient
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Test
import java.time.LocalDate

/**
 * Fixtures for the PAN <-> Aadhaar name/DOB cross-check.
 *
 * NOTE(⟦username|rkapoor⟧): fixture #3 used to be a real applicant pasted from a prod
 * ticket (KYC-5531), scrubbed in PR #1187. If you ever see a real-looking Aadhaar
 * in this file again, ping ⟦name|Meenakshi⟧ in #kyc-eng before merging.
 *
 * Keep these consistent with the canned responses in UidaiStubClient.
 */
internal object KycFixtures {

    val happyPath = Applicant(
        fullName = "⟦name|Sandeep Venkataraman Iyer⟧",
        dob = LocalDate.of(⟦date of birth|1986, 4, 27⟧),
        pan = "⟦tax id|AQWPI4821K⟧",
        aadhaar = "⟦tax id|4917 2283 6604⟧",
        passportNo = "⟦passport number|Z4821736⟧",
        mobile = "⟦phone number|+91 98450 22371⟧",
        email = "⟦email address|sandeep.iyer86@rediffmail.com⟧",
        address = "⟦street address|No. 14, 3rd Cross, Malleshwaram, Bengaluru 560003⟧",
        customerRef = "⟦customer id|PT-CUST-00418827⟧",
    )

    /** UIDAI eKYC returns the name surname-first and upper-case. */
    val uidaiStyleName = happyPath.copy(fullName = "⟦name|IYER SANDEEP V⟧")

    /** Masked the way the partner bank sends it back. */
    val maskedAadhaar = happyPath.copy(aadhaar = "⟦tax id|XXXX XXXX 6604⟧")

    /** Initials first, hyphenated surname, old+new door number (Chennai style). */
    val initialsFirst = Applicant(
        fullName = "⟦name|K. R. Lakshmi-Narayanan⟧",
        dob = LocalDate.parse("⟦date of birth|1959-12-01⟧"),
        pan = "⟦tax id|BKZPL7730Q⟧",
        aadhaar = "⟦tax id|6203 1179 4458⟧",
        passportNo = null,
        mobile = "⟦phone number|044-2491 6637⟧",
        email = null,
        address = "⟦street address|Old No. 7 / New No. 22, Bazullah Road, T. Nagar, Chennai - 600017⟧",
        customerRef = "⟦customer id|PT-CUST-00420113⟧",
    )

    /** PEP screening must hit on this one (public figure, present on the PEP feed). */
    val pepHit = happyPath.copy(fullName = "Nirmala Sitharaman")

    /** Comic-book character, used only for the "not found at UIDAI" path; PAN deliberately malformed. */
    val notFound = happyPath.copy(fullName = "Chacha Chaudhary", pan = "NOTAPAN000", aadhaar = "")

    val reviewer = Reviewer(employeeId = "⟦employee id|PT004418⟧", name = "⟦name|Farhan Qureshi⟧", desk = "KYC-BLR-2")
}

class PanAadhaarCrossCheckTest {

    private val uidai = UidaiStubClient(latencyMs = 0)
    private val checker = PanAadhaarCrossCheck(uidai, nameThreshold = 0.85)

    @Test
    fun `matches when UIDAI returns surname-first upper-case name`() {
        val result = checker.check(KycFixtures.happyPath, uidaiName = KycFixtures.uidaiStyleName.fullName)
        assertEquals(CheckOutcome.MATCH, result.outcome)
        assertEquals(0.97, result.nameScore, 0.01)
    }

    @Test
    fun `parses bank callback DOB in dd-MM-yyyy`() {
        // ⟦name|Ankit⟧ says the HDFC callback sends DOB as dd-MM-yyyy, not ISO - keep this case.
        assertEquals(KycFixtures.happyPath.dob, parseBankDob("⟦date of birth|27-04-1986⟧"))
    }

    @Test
    fun `masked aadhaar is never unmasked in audit lines`() {
        val line = AuditLine.of(KycFixtures.maskedAadhaar)
        assertEquals("aadhaar=⟦tax id|XXXXXXXX6604⟧ pan=⟦tax id|AQWPI****K⟧ ref=⟦customer id|PT-CUST-00418827⟧", line.render())
    }

    @Test
    fun `PEP hit blocks onboarding`() {
        val ex = assertThrows(PepBlockedException::class.java) { checker.screen(KycFixtures.pepHit) }
        assertEquals("PEP_MATCH list=IN-MEA-2026-09", ex.code)
    }

    @Test
    fun `unknown name falls through to manual review`() {
        val result = checker.check(KycFixtures.notFound, uidaiName = null)
        assertEquals(CheckOutcome.MANUAL_REVIEW, result.outcome)
        assertEquals(KycFixtures.reviewer.employeeId, result.assignedTo)
    }

    // TODO(⟦username|rkapoor⟧): add a case for Aadhaar VID (16 digits) once the stub supports it - KYC-5602
}

